part of '../model_analyzer.dart';

String _emitLibrary(
  Map<String, List<AnalyzedModel>> byFile, {
  required String outputPath,
  List<AnalyzedSeeder> seeders = const [],
}) {
  final paths = {
    ...byFile.keys,
    ...seeders.where((s) => s.hasRun).map((s) => s.path),
  }.toList()..sort();
  final all = byFile.values.expand((models) => models).toList();
  _resolveForeignKeys(all);
  final bridges = _resolveRelations(all);
  final names = <AnalyzedModel, String>{};
  final types = _EmissionTypes(all);
  final b = StringBuffer(
    '// GENERATED BY TikalORM - DO NOT MODIFY BY HAND.\n// ignore_for_file: camel_case_types\n',
  );
  if (all.any((m) => m.fields.any((f) => f.valueType == 'Uint8List'))) {
    b.writeln("import 'dart:typed_data';");
  }
  b.writeln("import 'package:tikal_orm/tikal_orm.dart' as orm;");
  final imports = <(String, String)>[];
  for (var i = 0; i < paths.length; i++) {
    final uri = Uri.file(
      p.relative(
        File(paths[i]).absolute.path,
        from: File(outputPath).absolute.parent.path,
      ),
    );
    imports.add((
      uri.toString(),
      'import ${_dartLiteral(uri.toString())} as m$i;',
    ));
    for (final model in byFile[paths[i]] ?? <AnalyzedModel>[]) {
      names[model] = 'm$i.${model.name}';
    }
  }
  for (final entry in types.prefixes.entries) {
    if (entry.value == 'orm') continue;
    final source = Uri.parse(entry.key);
    final uri = source.scheme == 'file'
        ? Uri.file(
            p.relative(
              source.toFilePath(),
              from: File(outputPath).absolute.parent.path,
            ),
          ).toString()
        : entry.key;
    imports.add((uri, 'import ${_dartLiteral(uri)} as ${entry.value};'));
  }
  imports.sort((a, b) {
    final length = a.$1.length.compareTo(b.$1.length);
    return length == 0 ? a.$1.compareTo(b.$1) : length;
  });
  if (imports.isNotEmpty) b.writeln('\n// Models');
  for (final entry in imports) {
    b.writeln(entry.$2);
  }
  b.writeln("\nexport 'package:tikal_orm/tikal_orm.dart';");
  all.sort((a, b) => a.name.compareTo(b.name));
  for (final model in all) {
    b.writeln(_generateModel(model, names, types));
  }
  b.writeln(
    '/// Discovered schema metadata; no DDL is executed on import.\nfinal tikalSchema = orm.SchemaSnapshot.fromJson(${jsonEncode(SchemaSnapshot([...all.map((m) => m.table), ...bridges]).toJson()).replaceAll(r'$', r'\$')});',
  );
  b.writeln(
    '/// Statically discovered model mappings.\nfinal tikalModels = orm.ModelRegistry([${all.map((m) => '${m.name}_.table').join(', ')}], schema: tikalSchema);',
  );
  b.writeln(
    const SeederAnalyzer().generateRegistry(seeders, {
      for (final (index, path) in paths.indexed) path: 'm$index',
    }),
  );
  b.writeln('''
/// Application entry point with the models discovered by generate/watch.
/// Configure explicitly; importing this file has no registration side effects.
// ignore: non_constant_identifier_names
final Tikal = orm.TikalClient(models: tikalModels);

''');
  return b.toString();
}

String _generateModel(
  AnalyzedModel model,
  Map<AnalyzedModel, String> names,
  _EmissionTypes types,
) {
  final name = names[model]!;
  final holder = '${model.name}_';
  const prefix = 'orm.';
  final b = StringBuffer(
    '/// Typed metadata for $name.\nfinal class $holder {\n',
  );
  for (final f in model.fields) {
    final c = f.column;
    final sqlType = f.referencedModel != null && !f.typeExplicit
        ? f.referencedModel!.fields
              .singleWhere((key) => key.column.primaryKey)
              .sqlType
        : f.sqlType;
    final columnType =
        f.conversion == null && f.valueType == 'String' && sqlType == 'text'
        ? '${prefix}TextColumn<$name>'
        : '${prefix}ModelColumn<$name, ${types.valueType(f)}>';
    final decoder = _decoderName(f);
    final decodeArg = f.conversion != null
        ? 'converter: ${types.resolve(f.conversion!.expression)}, '
        : decoder == null
        ? ''
        : 'decode: (row) => $prefix$decoder(row, ${_dartLiteral(c.name)}), ';
    b.writeln(
      '/// Typed binding for ${f.name}.\nstatic final ${f.name} = $columnType(name: ${_dartLiteral(c.name)}, sqlType: ${prefix}SqlType.$sqlType, read: (m) => m.${f.name}, write: (m, v) => m.${f.name} = v${f.nullable ? '' : '!'}, ${decodeArg}nativeTypes: ${jsonEncode(f.nativeTypes).replaceAll(r'$', r'\$')}, length: ${f.length}, precision: ${f.precision}, scale: ${f.scale}, nullable: ${c.nullable}, primaryKey: ${c.primaryKey}, unique: ${c.unique}, autoIncrement: ${c.identity}, hasDefault: ${c.defaultSql != null || c.identity});',
    );
  }
  final fieldsByName = {for (final f in model.fields) f.name: f};
  final args = <String>[];
  for (final p in model.constructor.parameters.parameters.where(
    (p) => p.isRequired,
  )) {
    final f = fieldsByName[p.name!.lexeme]!;
    final access = '${f.name}.decode(row)';
    args.add(
      '${p.isNamed ? '${f.name}: ' : ''}$access${f.nullable ? '' : '!'}',
    );
  }
  final table = model.table;
  b.writeln(
    '/// Mapping and persistence state for $name.\nstatic final table = ${prefix}TableDefinition<$name>(name: ${_dartLiteral(table.name)}, schema: ${_dartLiteral(table.schema ?? 'public')}, columns: [${model.fields.map((f) => f.name).join(', ')}], fromRowFactory: (row) => $name${model.constructor.name == null ? '' : '.${model.constructor.name!.lexeme}'}(${args.join(', ')}), create: ${_dartLiteral(table.createSql)},',
  );
  for (final f in model.fields) {
    if (f.version) b.writeln('versionColumn: ${f.name},');
    if (f.createdAt) b.writeln('createdAtColumn: ${f.name},');
    if (f.updatedAt) b.writeln('updatedAtColumn: ${f.name},');
    if (f.deletedAt) b.writeln('deletedAtColumn: ${f.name},');
  }
  b.writeln(');');
  b.write(_emitRelations(model, names, types));
  b.writeln('}');
  b.write(_emitLoadedRelations(model, names));
  b.writeln('''
/// Snapshot state for $name.
extension ${model.name}Persistence on $name {
  /// Whether this instance has a persisted snapshot.
  bool get isPersisted => $holder.table.isPersisted(this);
  /// Whether encoded values differ from the persisted snapshot.
  bool get isDirty => $holder.table.changedColumnNames(this).isNotEmpty;
  /// SQL column names whose encoded values changed.
  Set<String> changedColumnNames() => $holder.table.changedColumnNames(this);
}
''');
  return b.toString();
}

String _dartLiteral(String value) => jsonEncode(value).replaceAll(r'$', r'\$');

/// Chooses the engine-neutral decoder for a field whose raw driver value would
/// otherwise differ between engines (SQLite stores booleans, dates and JSON as
/// ints/text). Returns `null` when the default `row.as<T>` is already correct.
///
/// JSON decoders are only emitted for the variance-safe `Map<String, Object?>`
/// and `List<Object?>` shapes, so generated code stays assignable to the field.
String? _decoderName(AnalyzedField field) => switch (field.sqlType) {
  'boolean' => 'decodeBool',
  'date' || 'timestamp' || 'timestamptz' => 'decodeDateTime',
  'numeric' => 'decodeDecimal',
  'doublePrecision' => 'decodeDouble',
  'byteArray' => 'decodeBytes',
  'json' || 'jsonb' => switch (field.valueType) {
    'Map<String, Object?>' => 'decodeMap',
    'List<Object?>' => 'decodeList',
    'Object' => 'decodeJson',
    _ => null,
  },
  _ => null,
};
